        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueImpactDisplay', 'domainState.aiRevenueImpact',
                function(v) { return v > 0 ? '$' + v + 'M' : '--'; });
            uiManager.bind('costSavingsDisplay', 'domainState.aiCostSavings',
                function(v) { return v > 0 ? '$' + v + 'M' : '--'; });
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                function(v) { return v > 0 ? v + '/100' : '--'; });

            this._setupBudgetListeners();
            this._setupPosListener();
        }

        _setupBudgetListeners() {
            var ids = ['foundationalInput', 'offensiveInput', 'defensiveInput', 'talentInput'];
            var self = this;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el.__nexusBound) {
                    el.__nexusBound = true;
                    el.addEventListener('input', function() { self._updateBudgetDisplay(); });
                }
            });
            this._updateBudgetDisplay();

            var rids = ['reallocFoundInput', 'reallocOffInput', 'reallocDefInput', 'reallocTalentInput'];
            rids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el.__nexusBound) {
                    el.__nexusBound = true;
                    el.addEventListener('input', function() { self._updateReallocDisplay(); });
                }
            });
            this._updateReallocDisplay();
        }

        // Contrast-safe status colours. v1.0.0 painted pale dark-theme pastels (#fff176,
        // #a5d6a7, #ef9a9a) onto the cream #fffde7 panel — measured 1.13:1 / 1.6:1 / 2.1:1
        // against WCAG AA's 4.5:1. The "you still have $X to allocate" warning, the single most
        // important feedback in Round 1, was effectively invisible.
        _paint(el, state, html) {
            var C = {
                ok:    { color: '#1b5e20', bg: '#e8f5e9', border: '#2e7d32' },
                warn:  { color: '#6d4c00', bg: '#fff8e1', border: '#f9a825' },
                error: { color: '#a01818', bg: '#fdecea', border: '#c62828' }
            }[state];
            el.innerHTML = html;
            el.style.color           = C.color;
            el.style.background      = C.bg;
            el.style.borderColor     = C.border;
        }

        _updateBudgetDisplay() {
            var f = this._num('foundationalInput', 0);
            var o = this._num('offensiveInput', 0);
            var d = this._num('defensiveInput', 0);
            var t = this._num('talentInput', 0);
            var total = f + o + d + t;
            var rem   = this.TOTAL_BUDGET - total;

            var el = document.getElementById('budgetRemainingDisplay');
            if (!el) return;

            if (total === this.TOTAL_BUDGET) {
                this._paint(el, 'ok', this._tv('budget_ok', { budget: this.TOTAL_BUDGET }));
            } else if (rem > 0) {
                this._paint(el, 'warn', this._tv('budget_under', { total: total, rem: rem }));
            } else {
                this._paint(el, 'error', this._tv('budget_over', { total: total, over: Math.abs(rem) }));
            }
        }

        _updateReallocDisplay() {
            var el = document.getElementById('reallocRemainingDisplay');
            if (!el) return;

            var r = [this._num('reallocFoundInput', 0), this._num('reallocOffInput', 0),
                     this._num('reallocDefInput', 0),   this._num('reallocTalentInput', 0)];
            var net   = r.reduce(function(a, b) { return a + b; }, 0);
            var moved = r.reduce(function(a, b) { return a + (b > 0 ? b : 0); }, 0);

            if (net !== 0) {
                this._paint(el, 'error', this._tv('realloc_net_status',
                    { net: (net > 0 ? '+' : '') + net }));
            } else if (moved > this.MAX_REALLOC) {
                this._paint(el, 'error', this._tv('realloc_over_status',
                    { moved: moved, max: this.MAX_REALLOC }));
            } else {
                this._paint(el, 'ok', this._tv('realloc_ok_status',
                    { moved: moved, max: this.MAX_REALLOC }));
            }
        }

        _setupPosListener() {
            var cpEl = document.getElementById('competitivePosInput');
            var self = this;
            if (cpEl && !cpEl.__nexusBound) {
                cpEl.__nexusBound = true;
                cpEl.addEventListener('change', function() { self._updatePosDescription(); });
            }
            if (cpEl) this._updatePosDescription();
        }

        _updatePosDescription() {
            var cpEl   = document.getElementById('competitivePosInput');
            var descEl = document.getElementById('posDescriptionPanel');
            if (cpEl && descEl) {
                var val = parseInt(cpEl.value, 10) || 1;
                descEl.innerHTML = '<strong>' + this._posName(val) + '</strong><br>' + this._posDesc(val);
            }
        }

