        getChartData(state) {
            var self    = this;
            var history = state.domainState.scoreHistory || [];
            var labels  = history.map(function(_, i) {
                return self._t('round_label') + ' ' + (i + 1);
            });
            return { scoreChart: { labels: labels, datasets: [{ data: history }] } };
        }

        getPerformanceSummary(history) {
            var d = window.mySimulation.state.domainState;
            if (!d) return {};
            var score = d.totalScore || 0;

            var level = score >= 80 ? this._t('perf_excellent') :
                        score >= 60 ? this._t('perf_good') :
                        score >= 40 ? this._t('perf_adequate') :
                                      this._t('perf_developing');

            var insights = [];
            if (d.foundational < 25)            insights.push(this._t('insight_low_foundational'));
            if (d.regulatoryRiskExposure > 70)  insights.push(this._t('insight_high_reg_risk'));
            if (d.organizationalReadiness < 50) insights.push(this._t('insight_low_readiness'));
            if (d.talent < 20)                  insights.push(this._t('insight_low_talent'));
            if (d.competitivePositioning === 1 && d.foundational < 40) {
                insights.push(this._t('insight_orchestrator_underfunded'));
            }
            if (insights.length === 0) insights.push(this._t('insight_balanced'));

            return {
                totalScore:     score,
                aiRevenue:      d.aiRevenueImpact,
                aiCost:         d.aiCostSavings,
                govScore:       d.governanceQualityScore,
                orgReadiness:   d.organizationalReadiness,
                regulatoryRisk: d.regulatoryRiskExposure,
                performance:    level,
                insights:       insights
            };
        }

        getHint(state, results) {
            var d = state.domainState;
            var p = (results && results.period) || state.currentPeriod;

            if (p === 1) {
                if (d.foundational < 20) return this._t('hint_low_foundational');
                if (d.talent < 15)       return this._t('hint_low_talent');
            }
            if (p === 2) {
                // The card's consequence is revealed here — AFTER the governance decision has
                // been submitted. In v1.0.0 this same text was printed into the event panel
                // before the player chose, which simply told them the answer.
                var card = this._eventCard(d.eventCardIndex);
                if (card) return card.impact;
            }
            if (p === 3) {
                if (d.totalScore >= 75) return this._t('hint_excellent');
                if (d.totalScore < 45)  return this._t('hint_review');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',       label: 'Ronda',  i18nKey: 'col_period' },
                { key: 'results.aiRevenue',    label: 'Ingresos', i18nKey: 'col_revenue',
