        _updateBriefing(state) {
            var period  = (state && state.currentPeriod) || 1;
            var d       = (state && state.domainState) || {};
            var briefEl = document.getElementById('briefingText');
            var r1Panel = document.getElementById('round1Panel');
            var r2Panel = document.getElementById('round2Panel');
            var r3Panel = document.getElementById('round3Panel');
            var evPanel = document.getElementById('eventCardPanel');

            if (r1Panel) r1Panel.style.display = period === 1 ? 'block' : 'none';
            if (r2Panel) r2Panel.style.display = period === 2 ? 'block' : 'none';
            if (r3Panel) r3Panel.style.display = period === 3 ? 'block' : 'none';
            if (evPanel) evPanel.style.display = period === 2 ? 'block' : 'none';

            if (!briefEl) return;

            if (period === 1) {
                briefEl.innerHTML =
                    '<h4>' + this._t('brief1_title') + '</h4>' +
                    '<p>' + this._tv('brief1_body', { budget: this.TOTAL_BUDGET }) + '</p>' +
                    '<p><strong>' + this._t('brief_mission') + '</strong> ' + this._t('brief1_mission') + '</p>';

            } else if (period === 2) {
                briefEl.innerHTML =
                    '<h4>' + this._t('brief2_title') + '</h4>' +
                    '<p>' + this._tv('brief2_body', { max: this.MAX_REALLOC }) + '</p>';

                var card = this._eventCard(d.eventCardIndex);
                var evContent = document.getElementById('eventCardContent');
                if (card && evContent) {
                    // Title + what happened only. The consequence hint is withheld until after
                    // the decision (see getHint).
                    evContent.innerHTML =
                        '<h4>' + this._t('event_prefix') + ' ' + card.title + '</h4>' +
                        '<p>' + card.desc + '</p>';
                }

            } else if (period === 3) {
                briefEl.innerHTML =
                    '<h4>' + this._t('brief3_title') + '</h4>' +
                    '<p>' + this._t('brief3_body') + '</p>' +
                    '<p><strong>' + this._t('brief3_cumulative') + '</strong> ' +
                    this._t('foundational_label') + ': $' + (d.foundational || 0) + 'M | ' +
                    this._t('offensive_label')    + ': $' + (d.offensive    || 0) + 'M | ' +
                    this._t('defensive_label')    + ': $' + (d.defensive    || 0) + 'M | ' +
                    this._t('talent_label')       + ': $' + (d.talent       || 0) + 'M</p>';

                var self = this;
                setTimeout(function() { self._setupPosListener(); }, 200);
            }
        }

